static Bitmap Cut(Rectangle r,int w,int h,bool stone){using(var part=atlas.Clone(r,atlas.PixelFormat)){var b=Scale(part,w,h);for(int y=0;y<h;y++)for(int x=0;x<w;x++){Color c=b.GetPixel(x,y);if(c.A<180){b.SetPixel(x,y,Color.Transparent);continue;}if(stone){double lum=c.R*.3+c.G*.59+c.B*.11;Color best=palette[0];double min=999;foreach(Color q in palette){double dl=Math.Abs(lum-(q.R*.3+q.G*.59+q.B*.11));if(dl<min){min=dl;best=q;}}c=best;}else c=Color.FromArgb(255,c.R/12*12,c.G/12*12,c.B/12*12);b.SetPixel(x,y,c);}Clean(b);return b;}}
static void Clean(Bitmap b){var remove=new List<Point>();for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++){if(b.GetPixel(x,y).A==0)continue;int n=0;for(int yy=Math.Max(0,y-1);yy<=Math.Min(b.Height-1,y+1);yy++)for(int xx=Math.Max(0,x-1);xx<=Math.Min(b.Width-1,x+1);xx++)if((x!=xx||y!=yy)&&b.GetPixel(xx,yy).A>0)n++;if(n<2)remove.Add(new Point(x,y));}foreach(var p in remove)b.SetPixel(p.X,p.Y,Color.Transparent);}
static Bitmap StoneShape(int w,int h,Point[] points,int ox,int oy){var mask=B(w,h);Poly(mask,points,Color.White);var b=B(w,h);for(int y=0;y<h;y++)for(int x=0;x<w;x++)if(mask.GetPixel(x,y).A>0){bool edge=x==0||y==0||mask.GetPixel(Math.Max(0,x-1),y).A==0||mask.GetPixel(x,Math.Max(0,y-1)).A==0;bool shade=x==w-1||y==h-1||mask.GetPixel(Math.Min(w-1,x+1),y).A==0||mask.GetPixel(x,Math.Min(h-1,y+1)).A==0;b.SetPixel(x,y,edge?light:shade?dark:source.GetPixel((x+ox)%128,(y+oy)%128));}mask.Dispose();return b;}
