public static void Run(string root){dest=Path.Combine(root,"Docs/References/codex_k126_v1");source=new Bitmap(Path.Combine(root,"Game/Assets/_Project/Art/Battle/Resources/BattleArt/World/wall_stone_albedo.png"));atlas=new Bitmap(Path.Combine(dest,"generated_atlas.png"));
