Point[][] tops={P(30,79,65,79,65,119,30,119),P(30,79,52,79,52,83,59,83,59,89,65,89,65,119,30,119),P(30,95,39,95,39,99,48,99,48,104,58,104,58,108,65,108,65,119,30,119),P(30,112,39,112,39,110,47,110,47,114,59,114,59,116,65,116,65,119,30,119)};
string[] states={"intact","chipped","half_broken","stub"};var merlonSheet=B(384,128);for(int i=0;i<4;i++){var b=StoneShape(96,128,tops[i],0,1);Blit(merlonSheet,b,i*96,0);Save("merlon_"+states[i],b);}Save("merlon_states",merlonSheet);
Rectangle[] piles={new Rectangle(44,476,232,132),new Rectangle(322,431,296,181),new Rectangle(638,401,310,211),new Rectangle(975,366,324,251)};
foreach(string place in new[]{"field","walkway"})for(int s=0;s<3;s++)for(int v=0;v<3;v++){int w=28+s*18+(v-1)*2,h=(place=="field"?17:11)+s*(place=="field"?11:7);var b=B(96,128);using(var p=Cut(piles[(v+(place=="field"?0:1))%4],w,h,true))Blit(b,p,48-w/2,120-h);Save("rubble_"+place+"_"+new[]{"small","medium","large"}[s]+"_"+(v+1),b);}
var cracks=B(128,128);Point[][] paths={P(16,0,16,12,22,18,18,28,28,37,25,48,32,57,27,70,34,81,32,96,40,108,36,127),P(104,0,104,16,96,23,100,34,89,45,91,57,83,70,90,82,84,100,88,114,88,127),P(28,37,40,32,47,40,56,39,65,51),P(90,82,75,87,70,99,60,104)};foreach(var p in paths){var lit=new Point[p.Length];for(int i=0;i<p.Length;i++)lit[i]=new Point(p[i].X+1,p[i].Y);Line(cracks,lit,light,1);Line(cracks,p,dark,1);}for(int y=0;y<128;y++){cracks.SetPixel(0,y,Color.Transparent);cracks.SetPixel(127,y,Color.Transparent);}Save("wall_stage1_cracks",(Bitmap)cracks.Clone());
var gouge=(Bitmap)cracks.Clone();Point[][] pockets={P(37,37,63,37,63,55,54,55,54,66,33,66,33,48),P(78,77,102,77,102,94,95,94,95,108,74,108,74,91)};foreach(var p in pockets){Poly(gouge,p,dark);Line(gouge,p,light,1);}for(int y=20;y<120;y++)for(int x=10;x<118;x++)if(((x-78)*(x-78)+(y-70)*(y-70)/2<500)&&((x*11+y*17)%9<3)&&gouge.GetPixel(x,y).A==0)gouge.SetPixel(x,y,dark);Save("wall_stage2_gouges",gouge);
var hole=B(128,128);Poly(hole,Hole(),Color.White);Save("wall_stage3_cut_mask",(Bitmap)hole.Clone());var rim=B(128,128);for(int y=1;y<127;y++)for(int x=1;x<127;x++){if(hole.GetPixel(x,y).A>0)continue;int distance=99;for(int dy=-7;dy<=7;dy++)for(int dx=-7;dx<=7;dx++)if(x+dx>=0&&x+dx<128&&y+dy>=0&&y+dy<128&&hole.GetPixel(x+dx,y+dy).A>0)distance=Math.Min(distance,Math.Abs(dx)+Math.Abs(dy));if(distance<7){Color c=source.GetPixel(x,y);if(distance<=2)c=(x<60?dark:light);rim.SetPixel(x,y,c);}}Save("wall_stage3_breach_rim",(Bitmap)rim.Clone());var edge=B(32,128);for(int y=0;y<128;y++){int start=8+(y/10%3)*3;for(int x=start;x<30;x++)edge.SetPixel(x,y,x==start?light:x<start+3?dark:source.GetPixel(x,y));}Save("wall_stage3_edge_strip",edge);
