foreach(string effect in new[]{"dust","fire","smoke"}){var sheet=B(576,128);for(int f=0;f<6;f++){var frame=B(96,128);if(effect=="dust"){int w=26+f*7,h=18+f*4;using(var p=Cut(new Rectangle(f<2?80:370,950,f<2?185:350,215),w,h,false)){for(int y=0;y<h;y++)for(int x=0;x<w;x++)if(((x/3)*13+(y/3)*7)%13<f)p.SetPixel(x,y,Color.Transparent);Blit(frame,p,48-w/2,120-h-f*2);}}else{Rectangle rect=effect=="fire"?new Rectangle(786,992,112,181):new Rectangle(1080,944,154,224);int w=effect=="fire"?12+(f%3)*2:20+f%3*2,h=effect=="fire"?25+(f%3)*3:40+f%3*3;using(var p=Cut(rect,w,h,false)){var warped=B(w+4,h);for(int yy=0;yy<h;yy++)for(int xx=0;xx<w;xx++){int shift=yy<h-5?(int)Math.Round(Math.Sin((yy+f*3)*0.35)*1.5):0;warped.SetPixel(xx+2+shift,yy,p.GetPixel(xx,yy));}Blit(frame,warped,46-w/2,120-h);warped.Dispose();}}Clean(frame);Blit(sheet,frame,f*96,0);frame.Dispose();}Save(effect+"_6f",sheet);}
// 파공 적용 예시는 색칠된 구멍이 아니라 실제 알파를 뺀 뒤 테두리를 얹는다.
for(int s=0;s<4;s++){var panel=(Bitmap)source.Clone();if(s==1)Blit(panel,cracks,0,0);if(s==2){using(var p=new Bitmap(Path.Combine(dest,"native/wall_stage2_gouges.png")))Blit(panel,p,0,0);}if(s==3){for(int y=0;y<128;y++)for(int x=0;x<128;x++)if(hole.GetPixel(x,y).A>0)panel.SetPixel(x,y,Color.Transparent);Blit(panel,rim,0,0);}Save("wall_composite_stage"+s,panel);}cracks.Dispose();hole.Dispose();rim.Dispose();source.Dispose();atlas.Dispose();}
